def get_interpretation(gender, narrative, level, second_narrative=None):
    """
    Возвращает полную интерпретацию для пользователя
    gender: "М" или "Ж"
    narrative: "СБ", "ТФ", "УБ", "ЧВ"
    level: 1-6
    second_narrative: второй нарратив (если есть)
    """
    base_text = INTERPRETATIONS[gender][narrative][level]
    
    if second_narrative:
        second_text = f"\n\n*При этом* ты используешь мир *{NARRATIVE_NAMES[second_narrative]}* как средство. "
        second_text += "Это значит, что твоя основная цель — в твоём мире, но для её достижения ты используешь инструменты и возможности другого мира."
        return base_text + second_text
    
    return base_text


NARRATIVE_NAMES = {"СБ": "СИЛЫ", "ТФ": "ТРУДА", "УБ": "ЗНАНИЙ", "ЧВ": "ВНИМАНИЯ"}
